// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 timeJump, uint256 blockJump) public {
        // Restrict inputs: amount must be 10 ether to succeed, timeJump > 0 so timestamp advances
        vm.assume(amount == 10 ether);
        vm.assume(timeJump > 0);
        vm.assume(blockJump > 0);

        // Record the timestamp before the call
        uint256 timeBefore = block.timestamp;

        // Warp time forward and mine some blocks to satisfy the require
        vm.warp(block.timestamp + timeJump);
        vm.roll(block.number + blockJump);

        // Send exactly 10 ether to trigger fallback
        (bool success, ) = address(c).call{value: amount}("");

        // Read the state variable after the call
        uint256 storedTime = c.pastBlockTime();

        // The general rule: if the call succeeded, pastBlockTime should equal the block.timestamp at that moment
        // (the block.timestamp at the moment of the call is the current block.timestamp after vm.warp)
        if (success) {
            assertTrue(storedTime == block.timestamp, "pastBlockTime should equal current block.timestamp");
        }
    }
}

